   "titulo": "Semelhanças entre DITUIF e CI",
   "arquivo": "N13 — Fichamento — Semelhanças entre DITUIF e CI.md",
   "data": "2026-09-27",
   "paginas": "315–321 (artigo completo; páginas 1–7 do PDF)",
